// === Tab: mySketch ===
/*
THIS IS JUST ONE PART OF TODAY'S GENUARY!
I've remade the same (or similar) sketch in a bunch
of past versions of Processing.
See the whole explanation here: davepagurek.com/blog/sketch-evolution
*/
let fbo
let blur

function setup() {
	createCanvas(600, 600, WEBGL)
	fbo = createFramebuffer()
	blur = baseMaterialShader().modify(() => {
		const tex = uniformTexture(() => fbo.color)
		const depth = uniformTexture(() => fbo.depth)
		getPixelInputs((inputs) => {
			noiseDetail(2, 0.5)
			const offset = [
				noise(inputs.texCoord.x * 1000, inputs.texCoord.y * 1000, 0),
				noise(inputs.texCoord.x * 1000, inputs.texCoord.y * 1000, 100),
			]
			let d = getTexture(depth, inputs.texCoord).r
			for (let i = 0; i < 10; i++) {
				let angle = i + inputs.texCoord.x + inputs.texCoord.y
				let r = (i+1)/10 * 0.05
				d = min(d, getTexture(depth, inputs.texCoord + r*[cos(angle), sin(angle)]).r)
			}
			const noiseScale = abs(d - 0.92) * 0.6
			inputs.color = getTexture(tex, inputs.texCoord + offset * noiseScale)
			return inputs
		})
	})
	noStroke()
}

function draw() {
	fbo.begin()
	background(20, 20, 220)
	directionalLight(200, 0, 0, 0, 0, -1)
	directionalLight(250, 0, 0, -1, 1, 0)
	ambientLight(20, 20, 220)
	translate(0, 0, -500)
	rotateY(frameCount * 0.002)
	fill(255)

	let n = 10;
	for (let x = 0; x < n; x++) {
		for (let y = 0; y < n; y++) {
			for (let z = 0; z < n; z++) {
				push()
				let off = x + y + z;
				translate(
					map(x, 0, n-1, -1, 1) * 300,
					map(y, 0, n-1, -1, 1) * 300,
					map(z, 0, n-1, -1, 1) * 300,
				)
				sphere(16 * (1 + 0.5 * sin(frameCount * 0.05 + off)))
				pop()
			}
		}
	}
	fbo.end()

	push()
	shader(blur)
	plane(width, height)
	pop()
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
